#include "kstationControllerStartupServicesRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <memory>
#include <vector>
struct Ref:H8SEmulator{void history(){lastread=lastwrite=-1;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0xc3d0&&a<0xc4d0)||(a>=0xcd40&&a<0xcd70)||(a>=0xfffd20&&a<0xfffd24);}
struct RBus:H8SDevice{Ref&c;std::array<Event,8>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,8>e{};unsigned n=0;bool enabled=false;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc<2||argc>3)return 77;bool boot=argc==3;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);if(!boot)d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xc3d0,0x100);c->memmap(&x,0xcd40,0x30);c->memmap(&x,0xfffd20,4);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerStartupServicesRuntime rt;if((!boot&&!irq.bindVerifiedFirmware(*d,rom.data(),rom.size()))||!rt.bindBootResources(*d,rom.data(),rom.size())||(!boot&&!rt.bindMirroredFirmware(*d,rom.data(),rom.size())))return 2;y.enabled=true;uint64_t graphs=0,phases=0,events=0,shorts=0;using K=kstation::ControllerStartupServicesRuntime::Kind;for(unsigned scenario=0;scenario<13;++scenario)for(unsigned flags=boot?128:0;flags<256;++flags){rt.reset();irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};auto word=[&](uint32_t a,uint16_t v){put(a,v>>8);put(a+1,v);};for(unsigned i=0;i<0x100;++i)put(0xc3d0+i,uint8_t(i*17+flags));for(unsigned i=0;i<0x30;++i)put(0xcd40+i,uint8_t(i*31+flags));uint32_t tick=0xfedc0000u|uint16_t(flags*257);for(unsigned i=0;i<4;++i)put(0xfffd20+i,uint8_t(tick>>(8*(3-i))));unsigned slot=scenario>=1&&scenario<=10?(scenario-1)%5:flags;K kind=scenario==0?K::ReadAdc:scenario<=5?K::ClearScheduler:scenario<=10?K::ArmScheduler:scenario==11?K::ClockInitialize:K::ReadTick;constexpr uint16_t samples[]={0,1,255,256,257,0x7fff,0x8000,0xffff};word(0xc3d0+uint8_t(flags*2),samples[flags&7]);uint32_t callback=(flags&1)?0x9a6c43b2:0x43b2;uint16_t delay=uint16_t(flags*257);uint32_t entry=scenario==0?0x5cc:scenario<=5?0x388c+0x5c*slot:scenario<=10?0x3896+0x5c*slot:scenario==11?0x4444:0x9aa;c->pc=c->makepc(entry);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg8(14)=int8_t(flags);c->reg32(5)=int32_t(callback);c->reg16(6)=int16_t(delay);c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=((flags&0x81)==0x81)?1:0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history();d->lastRead=d->lastWrite=-1;if(!rt.start(kind,uint8_t(slot),callback,delay))return 3;for(unsigned k=0;rt.active();++k){if(k>1000)return 4;auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=rt.nextClocks(*d,irq);if(!cost){std::fprintf(stderr,"cost pc=%x scenario=%u flags=%u\n",at,scenario,flags);return 5;}if(phases%31==0){auto before=d->cycles;for(unsigned b=0;b<cost;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}}c->step();auto r=rt.advanceBefore(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x scenario=%u flags=%u clocks=%llu/%llu io=%u/%u\n",at,scenario,flags,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i)if(x.e[i].at!=y.e[i].at||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x scenario=%u addr=%x/%x value=%x/%x time=%llu/%llu\n",at,scenario,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].at,y.e[i].at);return 8;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;if(kind==K::ReadAdc&&rt.value()!=uint8_t(c->reg8(14)))return 10;if(kind==K::ReadTick&&rt.value()!=uint16_t(c->reg16(6)))return 11;if(std::memcmp(c->memory+0xcd40,d->memory+0xcd40,0x30))return 12;++graphs;}if(boot){y.enabled=false;d->loadMemory(rom.data(),rom.size(),0x400000);d->memory[0x4005cc]^=1;if(rt.bindMirroredFirmware(*d,rom.data(),rom.size()))return 13;d->memory[0x4005cc]^=1;if(!rt.bindMirroredFirmware(*d,rom.data(),rom.size()))return 14;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
